package cn.huankan.collector;
import java.math.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
public final class BlsFileAdapter {
 public record Point(LocalDate date,BigDecimal value,String rawValue,List<Map<String,String>> footnotes,String line,Map<String,String> metadata){}
 static List<Map<String,String>> rows(byte[] bytes){String[] lines=new String(bytes,StandardCharsets.UTF_8).split("\\r?\\n");if(lines.length<2)throw new IllegalArgumentException("官方TSV缺少表头或观测");String[] names=lines[0].split("\\t",-1);var result=new ArrayList<Map<String,String>>();for(int n=1;n<lines.length;n++){if(lines[n].isBlank())continue;String[] cells=lines[n].split("\\t",-1);if(cells.length!=names.length)throw new IllegalArgumentException("官方TSV列数变化");var r=new LinkedHashMap<String,String>();for(int i=0;i<names.length;i++)r.put(names[i].strip(),cells[i].strip());r.put("_raw_line",lines[n]);result.add(r);}return result;}
 public static List<Point> parse(byte[] series,byte[] data,byte[] footnotes,int startYear,int endYear){if(startYear<1900||endYear<startYear||endYear-startYear>9)throw new IllegalArgumentException("批量同步仅允许最多10个年份");var meta=rows(series).stream().filter(x->"CUUR0000SA0".equals(x.get("series_id"))).findFirst().orElseThrow(()->new IllegalArgumentException("缺少官方series定义"));if(!"U".equals(meta.get("seasonal"))||!"R".equals(meta.get("periodicity_code"))||!"SA0".equals(meta.get("item_code"))||!"1982-84=100".equals(meta.get("base_period")))throw new IllegalArgumentException("series单位、季调或频率未确认");var notes=new HashMap<String,String>();for(var n:rows(footnotes))notes.put(n.get("footnote_code"),n.get("footnote_text"));var result=new ArrayList<Point>();var unique=new HashSet<LocalDate>();for(var r:rows(data)){if(!"CUUR0000SA0".equals(r.get("series_id")))continue;int year=Integer.parseInt(r.get("year"));if(year<startYear||year>endYear)continue;String period=r.get("period");if("M13".equals(period))continue;if(period==null||!period.matches("M(0[1-9]|1[0-2])"))throw new IllegalArgumentException("观测期不是实际月份");LocalDate date=LocalDate.of(year,Integer.parseInt(period.substring(1)),1);if(!unique.add(date))throw new IllegalArgumentException("重复观测期需要隔离核查");String raw=r.get("value");var f=new ArrayList<Map<String,String>>();for(String code:Objects.toString(r.get("footnote_codes"),"").split(",")){if(code.isBlank())continue;if(!notes.containsKey(code.strip()))throw new IllegalArgumentException("脚注代码未在官方词典中确认");f.add(Map.of("code",code.strip(),"text",notes.get(code.strip())));}result.add(new Point(date,raw.equals("-")||raw.isBlank()?null:new BigDecimal(raw),raw,f,r.get("_raw_line"),meta));}if(result.isEmpty())throw new IllegalArgumentException("请求范围内没有官方观测");return result;}
}
